-- CipherTrainer database schema (PostgreSQL 16).
-- NOTE: "user" is a reserved word in PostgreSQL, so the table name must always be quoted.

CREATE TYPE "algorithm_type" AS ENUM (
	'STREAM',
	'SUBSTITUTION',
	'TRANSPOSITION'
);

CREATE TABLE IF NOT EXISTS "algorithm" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(30) NOT NULL,
	"type" ALGORITHM_TYPE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "lesson" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"algorithm_id" BIGINT,
	"title" VARCHAR(30) NOT NULL,
	"content_text" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "challenge" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"algorithm_id" BIGINT NOT NULL,
	"cipher_text" TEXT NOT NULL,
	"plain_text" TEXT NOT NULL,
	"difficulty_level" SMALLINT NOT NULL CHECK("difficulty_level" BETWEEN 1 AND 5),
	"reward_points" INTEGER NOT NULL CHECK("reward_points" >= 0),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "hint" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"challenge_id" BIGINT NOT NULL,
	"hint_text" TEXT NOT NULL,
	"cost_points" INTEGER NOT NULL CHECK("cost_points" >= 0),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "attempt" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"user_id" BIGINT NOT NULL,
	"challenge_id" BIGINT NOT NULL,
	"is_successful" BOOLEAN,
	"time_taken_seconds" INTEGER CHECK("time_taken_seconds" >= 0),
	"attempt_date" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "achievement" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(30) NOT NULL,
	"description" TEXT,
	"criteria" JSONB NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "user_achievement" (
	"user_id" BIGINT NOT NULL,
	"achievement_id" BIGINT NOT NULL,
	"unlocked_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("user_id", "achievement_id")
);

CREATE TABLE IF NOT EXISTS "user" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"username" VARCHAR(30) NOT NULL UNIQUE,
	"password_hash" VARCHAR(128) NOT NULL,
	"total_score" INTEGER NOT NULL DEFAULT 0 CHECK("total_score" >=0),
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"is_admin" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

ALTER TABLE "lesson"
ADD FOREIGN KEY("algorithm_id") REFERENCES "algorithm"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "user_achievement"
ADD FOREIGN KEY("achievement_id") REFERENCES "achievement"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "hint"
ADD FOREIGN KEY("challenge_id") REFERENCES "challenge"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "challenge"
ADD FOREIGN KEY("algorithm_id") REFERENCES "algorithm"("id")
ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "attempt"
ADD FOREIGN KEY("user_id") REFERENCES "user"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "attempt"
ADD FOREIGN KEY("challenge_id") REFERENCES "challenge"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "user_achievement"
ADD FOREIGN KEY("user_id") REFERENCES "user"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
